  function dropTarget(node,group){node.ondragover=e=>{if(!dragged||blocked||fatal||orderLocked())return;e.preventDefault();node.classList.add('drop-over');};node.ondragleave=e=>{if(!node.contains(e.relatedTarget))node.classList.remove('drop-over');};node.ondrop=async e=>{e.preventDefault();if(orderLocked())return;node.classList.remove('drop-over');const id=dragged;dragged=null;if(!id)return;const target=e.target.closest('.task-card');const before=target?.dataset.taskId;await moveTask(id,group==='later'?'later':'week',selectedWeek,group==='later'?null:group,before);};}
  async function moveTask(id,placement,week=selectedWeek,status=null,before=null){if(before===id)return;await commit(s=>{const t=s.tasks.find(t=>t.id===id);if(!t||t.lifecycle!=='active')return;const old=clone(t);if(placement==='week'&&(week<currentWeek()||!validDate(week)))throw new Error('Можно выбрать текущую или будущую неделю.');t.placement=placement;t.weekId=placement==='later'?null:monday(week);if(status)t.status=status;if(old.weekId!==t.weekId)withdraw(s,old,placement==='later'?'later':'manual_move');t.order=endOrder(s,t);if(before&&before!==id){const list=s.tasks.filter(a=>sameGroup(a,t)&&a.id!==id).sort((a,b)=>a.order-b.order);const i=list.findIndex(a=>a.id===before);list.splice(i<0?list.length:i,0,t);list.forEach((a,i)=>a.order=i);}t.updatedAt=now();syncRow(s,t,'manual');});}
