  function destination(includeLater=false){const box=el('div');const label=el('label','','Неделя');const input=el('input');input.type='date';input.id='destination-week';input.min=currentWeek();input.max='2100-12-25';input.value=selectedWeek>=currentWeek()?selectedWeek:currentWeek();label.append(input);box.append(label);if(includeLater){const l=el('label','check-label');const cb=el('input');cb.type='checkbox';cb.id='destination-later';l.append(cb,el('span','','В общий список «позже»'));box.append(l);}return box;}
