  function openEditor(id=null,preset={},source=null){if(blocked||fatal)return;editing=id;const t=id?state.tasks.find(t=>t.id===id):null;draft=t?clone(t):{id:uid(),boardId:state.selectedBoardId,title:'',description:'',type:filters.type==='personal'?'personal':'work',status:preset.status||'new',placement:preset.placement||'week',weekId:preset.placement==='later'?null:(selectedWeek>=currentWeek()?selectedWeek:currentWeek()),urgent:false,reportImportant:false,dueDate:null,contact:'',checklist:[],order:0,lifecycle:'active',createdAt:now(),updatedAt:now(),completedAt:null,completedLocalDate:null,completedWeekId:null,autoCarryCount:0,deletedAt:null,trashRestoreState:null};if(source)Object.assign(draft,{title:`Копия - ${source.title}`.slice(0,200),description:source.description,type:source.type,urgent:source.urgent,contact:source.contact,checklist:source.checklist.map(i=>({id:uid(),text:i.text,done:false}))});draftInitial=JSON.stringify(draft);dirty=false;
    for(const o of $('task-status').options)o.textContent=state.settings.statusLabels[o.value];$('task-title').value=draft.title;$('task-description').value=draft.description;$('task-type').value=draft.type;$('task-status').value=draft.status;$('task-placement').value=draft.placement;$('task-week').value=draft.weekId||currentWeek();$('task-week').min=draft.weekId&&draft.weekId<currentWeek()?draft.weekId:currentWeek();$('task-week').max='2100-12-25';$('task-urgent').checked=draft.urgent;$('task-report-important').checked=!!draft.reportImportant;$('task-due').value=draft.dueDate||'';$('task-contact').value=draft.contact;$('checklist-new').value='';$('form-error').hidden=true;$('editor-save-status').textContent=id?'Изменения сохраняются автоматически':'';$('editor-eyebrow').textContent=id?'КАРТОЧКА ЗАДАЧИ':'НОВАЯ ЗАДАЧА';$('editor-title').textContent=id?'Детали задачи':'Что нужно сделать?';$('task-submit').textContent=id?'Готово':'Создать задачу';$('task-complete').hidden=!t||t.lifecycle!=='active';$('editor-info').textContent=t?.lifecycle==='completed'?'Архивная задача. Изменение текста не меняет прошлые сводки.':!t&&selectedWeek<currentWeek()?'Новая задача будет создана в текущей неделе.':'';for(const k of ['task-type','task-status','task-placement','task-week','task-urgent','task-due','task-contact'])$(k).disabled=t?.lifecycle==='completed';renderChecklist();refreshDraftHints();$('editor').showModal();$('task-title').focus();}
  function readDraft(){draft.title=$('task-title').value;draft.description=$('task-description').value;draft.type=$('task-type').value;draft.status=$('task-status').value;draft.placement=$('task-placement').value;const w=$('task-week').value;draft.weekId=draft.placement==='later'?null:(validDate(w)?monday(w):w);draft.urgent=$('task-urgent').checked;draft.reportImportant=$('task-report-important').checked;draft.dueDate=$('task-due').value||null;draft.contact=$('task-contact').value;refreshDraftHints();}
