  function renderChecklist(){const list=$('checklist');list.replaceChildren();draft.checklist.forEach((item,index)=>{const row=el('div','checklist-row');const done=el('input');done.type='checkbox';done.checked=item.done;done.setAttribute('aria-label',`Выполнен пункт ${index+1}`);done.onchange=()=>{item.done=done.checked;scheduleSave();$('checklist-progress').textContent=`${draft.checklist.filter(i=>i.done).length} из ${draft.checklist.length}`;};const text=el('input','item-text');text.value=item.text;text.setAttribute('aria-label',`Пункт ${index+1}`);text.oninput=()=>{item.text=text.value;scheduleSave();};const up=button('↑','',()=>{if(index){[draft.checklist[index-1],draft.checklist[index]]=[item,draft.checklist[index-1]];renderChecklist();scheduleSave();}});up.setAttribute('aria-label',`Поднять пункт ${index+1}`);up.disabled=index===0;const down=button('↓','',()=>{if(index<draft.checklist.length-1){[draft.checklist[index+1],draft.checklist[index]]=[item,draft.checklist[index+1]];renderChecklist();scheduleSave();}});down.setAttribute('aria-label',`Опустить пункт ${index+1}`);down.disabled=index===draft.checklist.length-1;const remove=button('×','',()=>{draft.checklist.splice(index,1);renderChecklist();scheduleSave();});remove.setAttribute('aria-label',`Удалить пункт ${index+1}`);row.append(done,text,up,down,remove);list.append(row);});$('checklist-progress').textContent=draft.checklist.length?`${draft.checklist.filter(i=>i.done).length} из ${draft.checklist.length}`:'';}
